<section class="panel table-panel"><form class="filterbar" method="get" action="<?= site_url($path) ?>"><label class="search-field"><span>Cari data</span><input type="search" name="q" value="<?= h($p['q']) ?>" placeholder="Kode atau nama"></label><label><span>Status</span><select name="status"><option value="">Semua</option><option value="aktif" <?= $p['status']==='aktif'?'selected':'' ?>>Aktif</option><option value="arsip" <?= $p['status']==='arsip'?'selected':'' ?>>Arsip</option></select></label><label><span>Per halaman</span><select name="per_page"><?php foreach (array(10,25,50,100) as $n): ?><option value="<?= $n ?>" <?= $p['per_page']===$n?'selected':'' ?>><?= $n ?></option><?php endforeach; ?></select></label><button class="button button-dark button-small" type="submit">Terapkan</button><a class="button button-quiet button-small" href="<?= site_url($path) ?>">Reset</a></form><div class="table-wrap"><table><thead><tr><th>Kode</th><th>Nama</th><th>Status</th><th>Terakhir diubah</th><th>Aksi</th></tr></thead><tbody><?php foreach ($rows as $r): ?><tr><td class="mono"><?= h($r['code']) ?></td><td><strong><?= h($r['name']) ?></strong><?php if ($r['description']): ?><small class="cell-sub"><?= h(mb_strimwidth($r['description'],0,75,'…')) ?></small><?php endif; ?></td><td><span class="pill <?= $r['active']?'pill-green':'pill-muted' ?>"><?= $r['active']?'Aktif':'Arsip' ?></span></td><td><?= h(date('d M Y',strtotime($r['updated_at']))) ?></td><td class="actions-cell"><?php if ($can_edit): ?><a class="row-link" href="<?= site_url('admin/master/'.$def['slug'].'/'.$r['id'].'/ubah') ?>">Ubah</a><?php endif; ?><?php if ($can_archive): ?><form method="post" action="<?= site_url('admin/master/'.$def['slug'].'/'.$r['id'].'/status') ?>" onsubmit="return confirm('Ubah status master ini?')"><?= csrf_input() ?><button type="submit" class="text-button"><?= $r['active']?'Arsipkan':'Aktifkan' ?></button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="5" class="empty-cell">Belum ada data yang sesuai filter.</td></tr><?php endif; ?></tbody></table></div><?php $this->load->view('partials/pagination'); ?></section>
